package dev.zomboid.hordes;
import java.util.*;
public final class LootNerf {
 public static final int OTHER=0,WEAPON=1,ARMOR=2,AMMO=3,CLOTH=4,TOOL=5,VALUABLE=6;
 static Object c(Object o,String n,Object...a){return ZoneReflection.call(o,n,a);}static boolean yes(Object o){return Boolean.TRUE.equals(o);}static double r(Object level){return ((Number)c(ZoneReflection.get(level,"random"),"nextDouble")).doubleValue();}
 public static int tier(int q){return Math.max(0,Math.min(5,q));}public static int capacity(int q,double factor){return Math.min(21,Math.max(0,(int)Math.ceil((2+tier(q))*factor)));}public static int ammoCap(int q){return new int[]{2,3,4,6,8,12}[tier(q)];}public static double probability(int q,double percent){return Math.min(1,Math.max(0,percent)*new double[]{.25,.5,1,1.5,2,2.5}[tier(q)]/100);}
 static String id(Object s){return String.valueOf(c(ZoneReflection.get(ZoneReflection.type("net.minecraft.core.registries.BuiltInRegistries"),"ITEM"),"getKey",c(s,"getItem"))).toLowerCase(Locale.ROOT);}
 static boolean family(Object item,String name){for(Class<?>t=item.getClass();t!=null;t=t.getSuperclass())if(t.getSimpleName().equals(name))return true;return false;}
 public static int kind(Object stack){String id=id(stack),p=id.substring(id.indexOf(':')+1);Object item=c(stack,"getItem");if(p.equals("ammo")||p.contains("ammunition")||p.equals("arrow")||p.equals("spectral_arrow"))return AMMO;
  if(id.startsWith("selfexpression:")&&!p.contains("armor")&&!p.contains("stalker")&&!p.contains("zombie_survivor"))return CLOTH;
  if(id.startsWith("minecraft:leather_"))return CLOTH;
  if(family(item,"ArmorItem")||p.contains("backpack")||p.contains("vest")||p.contains("helmet")||p.contains("chestplate")||p.contains("leggings")||p.contains("boots")||p.contains("nvg")||p.contains("night_vision"))return ARMOR;
  if(p.contains("kinetic_gun")||family(item,"SwordItem")||p.endsWith("_sword")||p.endsWith("_axe")||p.contains("baseball_bat")||p.contains("machete")||p.contains("knife")||p.equals("bow")||p.equals("crossbow")||id.startsWith("lrtactical:")&&(p.contains("bat")||p.contains("spear")))return WEAPON;
  if(p.contains("diamond")||p.contains("netherite")||p.equals("ancient_debris")||p.equals("enchanted_book"))return VALUABLE;
  if(family(item,"DiggerItem")||p.endsWith("_pickaxe")||p.endsWith("_shovel")||p.endsWith("_hoe")||p.equals("fishing_rod")||p.equals("shears")||p.contains("wrench")||p.contains("crowbar"))return TOOL;return OTHER;
 }
 static boolean same(Object a,Object b){return yes(c(ZoneReflection.type("net.minecraft.world.item.ItemStack"),"isSameItemSameComponents",a,b));}
 public static List<Object>filter(List<?>input,Object level,int quality,List<?>owned){
  if(!WorldTuning.flag("loot_balance_todos"))return new ArrayList<>(input);int q=tier(quality);List<Object>keep=new ArrayList<>();List<List<Object>>groups=new ArrayList<>();for(int k=0;k<7;k++)groups.add(new ArrayList<>());Set<Integer>matched=new HashSet<>();
  for(Object original:input){if(yes(c(original,"isEmpty")))continue;boolean protectedItem=false;for(int j=0;j<owned.size();j++)if(!matched.contains(j)&&same(original,owned.get(j))){matched.add(j);protectedItem=true;break;}Object stack=c(original,"copy");if(protectedItem){keep.add(stack);continue;}groups.get(kind(stack)).add(stack);}
  int cap=capacity(q,WorldTuning.get("loot_suministros_cantidad"));
  List<Object>supplies=groups.get(OTHER);supplies.addAll(groups.get(TOOL));for(int n=0;n<cap&&!supplies.isEmpty();n++){Object s=supplies.remove((int)(r(level)*supplies.size()));c(s,"setCount",Math.min(((Number)c(s,"getCount")).intValue(),kind(s)==TOOL?1:1+q/2));keep.add(s);}
  List<Object>clothes=groups.get(CLOTH);for(int n=0;n<Math.min(2,clothes.size());n++){Object s=clothes.get(n);c(s,"setCount",1);keep.add(s);}
  for(int k:new int[]{WEAPON,ARMOR,AMMO,VALUABLE}){double percent=k==WEAPON?WorldTuning.get("loot_arma_rara"):k==AMMO?WorldTuning.get("loot_municion_rara"):WorldTuning.get("loot_armadura_rara");List<Object>pool=groups.get(k);if(cap<=0||pool.isEmpty()||r(level)>=probability(q,percent))continue;Object s=pool.get((int)(r(level)*pool.size()));c(s,"setCount",k==AMMO?Math.min(ammoCap(q),((Number)c(s,"getCount")).intValue()):1);if(k==WEAPON)unloadGenerated(s,q);keep.add(s);}
  return keep;
 }
 static void unloadGenerated(Object s,int q){try{Class<?>type=Class.forName("com.tacz.guns.api.item.IGun");Object gun=c(type,"getIGunOrNull",s);if(gun!=null){int n=((Number)c(gun,"getCurrentAmmoCount",s)).intValue();c(gun,"setCurrentAmmoCount",s,Math.min(n,Math.min(4,ammoCap(q))));c(gun,"setBulletInBarrel",s,false);}}catch(ClassNotFoundException e){}catch(RuntimeException e){System.getLogger("Scarcity33").log(System.Logger.Level.WARNING,"No se pudo limitar cargador generado",e);}}
 public static void body(Object corpse,Object level,Object event){try{Object entity=c(event,"getEntity");String type=String.valueOf(c(c(entity,"getType"),"getDescriptionId"));if(type.contains("tacznpcs")||type.contains("bandit"))return;List<Object>owned=new ArrayList<>();for(Object s:(Iterable<?>)c(entity,"getArmorSlots"))if(!yes(c(s,"isEmpty")))owned.add(s);for(String hand:new String[]{"getMainHandItem","getOffhandItem"}){Object s=c(entity,hand);if(!yes(c(s,"isEmpty")))owned.add(s);}Object inv=ZoneReflection.get(corpse,"inventory");List<Object>list=new ArrayList<>();for(int i=0;i<((Number)c(inv,"getContainerSize")).intValue();i++)list.add(c(inv,"getItem",i));List<Object>out=filter(list,level,((Number)ZoneReflection.get(corpse,"quality")).intValue(),owned);c(inv,"clearContent");for(int i=0;i<out.size();i++)c(inv,"setItem",i,out.get(i));CorpseProfessions.limitTools(inv);}catch(RuntimeException e){System.getLogger("Scarcity33").log(System.Logger.Level.ERROR,"No se pudo reducir loot del cuerpo",e);}}
 @SuppressWarnings("unchecked")public static Object container(Object object,Object block,Object params){if(!(object instanceof List<?>list))return object;boolean supported=false;for(Class<?>t=block.getClass();t!=null;t=t.getSuperclass())if(t.getSimpleName().toLowerCase(Locale.ROOT).contains("chest")||t.getSimpleName().toLowerCase(Locale.ROOT).contains("barrel"))supported=true;if(!supported)return object;List<Object>result=filter(list,c(params,"getLevel"),0,List.of());((List<Object>)object).clear();((List<Object>)object).addAll(result);return object;}
}
